// Breaking change 4: The Cosmos provider no longer supports synchronous I/O.
// ToList() and SaveChanges() must become ToListAsync() and SaveChangesAsync().
class SyncJob
{
    async Task RunAsync(BlogContext context)
    {
        var blogs = await context.Blogs.ToListAsync();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        await context.SaveChangesAsync();
    }
}

